function Fail($m) {
    Write-Host ''
    Write-Host "  $m" -ForegroundColor Red
    Write-Host ''
    Read-Host '  Press Enter to close'
    exit 1
}

function ApplySpec([byte[]]$buf, [string]$s) {
    foreach ($run in $s.Split(';')) {
        if ($run.Length -eq 0) { continue }
        $c = $run.IndexOf(',')
        $o = [int]$run.Substring(0, $c)
        $h = $run.Substring($c + 1)
        for ($k = 0; $k -lt $h.Length; $k += 2) {
            $buf[$o + $k / 2] = [Convert]::ToByte($h.Substring($k, 2), 16)
        }
    }
}

Write-Host ''
Write-Host '  Way of the Samurai 4 - framerate patch' -ForegroundColor Cyan
Write-Host '  ======================================'
Write-Host ''

if (-not (Test-Path $exe)) { Fail 'WayOfTheSamurai4.exe not found. Put these files IN the game folder.' }
if (-not (Test-Path $mdb)) { Fail "MotionDatabase.l not found at:`n    $mdb" }

function Ed($h) {
    if ($h -eq $GOG_SHA)   { return 'GOG' }
    if ($h -eq $STEAM_SHA) { return 'Steam (unpacked)' }
    return $null
}

# --- pick the STOCK exe to patch from ---------------------------------------
# Prefer a valid stock backup (.orig) so re-runs are stable; otherwise use the
# live exe. A stale or still-packed .orig must NOT block a decrypted live exe.
$src = $null; $ed = $null
if (Test-Path $exeOrig) {
    $oh = (Get-FileHash $exeOrig -Algorithm SHA256).Hash
    $ed = Ed $oh
    if ($ed) { $src = $exeOrig }
}
if (-not $src) {
    $lh = (Get-FileHash $exe -Algorithm SHA256).Hash
    $ed = Ed $lh
    if ($ed) {
        $src = $exe
        Copy-Item $exe $exeOrig -Force
        Write-Host '  Backed up stock exe -> WayOfTheSamurai4.exe.orig' -ForegroundColor Green
    }
    elseif ($lh -eq $PACKED_SHA) {
        Fail ("This WayOfTheSamurai4.exe still has SteamStub DRM (code encrypted on disk).`n" +
              "  Unpack it first (e.g. Steamless), replace WayOfTheSamurai4.exe with the`n" +
              "  unpacked exe, then run this again.  Nothing was changed.")
    }
    else {
        Fail ("Unrecognised WayOfTheSamurai4.exe.`n    yours: $lh`n" +
              "  Supported stock:`n    GOG            $GOG_SHA`n    Steam unpacked $STEAM_SHA`n" +
              "  If this exe is already patched, put your STOCK (decrypted) exe back as`n" +
              "  WayOfTheSamurai4.exe and run again.  Nothing was changed.")
    }
}

# --- MotionDatabase.l stock ---------------------------------------------------
if (-not (Test-Path $mdbOrig)) { Copy-Item $mdb $mdbOrig }
$mh = (Get-FileHash $mdbOrig -Algorithm SHA256).Hash
if ($mh -ne $MDB_SHA) {
    $lm = (Get-FileHash $mdb -Algorithm SHA256).Hash
    if ($lm -eq $MDB_SHA) { Copy-Item $mdb $mdbOrig -Force; $mh = $lm }
}
if ($mh -ne $MDB_SHA) { Fail "MotionDatabase.l does not match the expected stock file.`n    yours: $mh" }

Write-Host "  Detected edition: $ed" -ForegroundColor Cyan
Write-Host '  Verified your original exe and MotionDatabase.l.' -ForegroundColor Green

$eb = [IO.File]::ReadAllBytes($exeOrig)
$mb = [IO.File]::ReadAllBytes($mdbOrig)

foreach ($r in 60) {
    $e = New-Object byte[] $eb.Length; [Array]::Copy($eb, $e, $eb.Length)
    $m = New-Object byte[] $mb.Length; [Array]::Copy($mb, $m, $mb.Length)
    $key = if ($ed -eq 'GOG') { "GOG_$r" } else { "STM_$r" }
    ApplySpec $e (Get-Variable -Name $key -ValueOnly)
    ApplySpec $m (Get-Variable -Name "MDB_$r" -ValueOnly)
    [IO.File]::WriteAllBytes("$exe.fps$r", $e)
    [IO.File]::WriteAllBytes("$mdb.fps$r", $m)
    Write-Host ("  Built {0,3} fps (exe + motion data)" -f $r) -ForegroundColor Green
}

Copy-Item "$exe.fps60" $exe -Force
Copy-Item "$mdb.fps60" $mdb -Force
Write-Host ''
Write-Host '  Installed 60 fps.' -ForegroundColor Cyan
Write-Host '  The launcher can switch between the stock 30 fps and patched 60 fps pairs.'
Write-Host ''
Read-Host '  Press Enter to close'
